const listarPendientes = `-- name: ListarPendientes :many
SELECT id, empresa_id, sistema, operacion, idempotency_key, entidad, entidad_id, metodo, ruta, payload, depende_de, datos_incompletos, estado, intentos, proximo_intento, tomado_en, ultimo_error, ultimo_status, hecho_en, evento_id, version, created_at, updated_at, conflicto, conflicto_payload, conflicto_en, respuesta, plantilla, por_resolver, verificar, tecnico_usuario_id, codigo_error, resuelto_motivo, resuelto_por, resuelto_en FROM integracion.pendientes
WHERE ($1::bigint = 0 OR id < $1)
  AND ($2::boolean OR empresa_id IS NOT DISTINCT FROM $3::bigint)
  AND ($4::text IS NULL OR entidad = $4)
  AND ($5::text IS NULL OR entidad_id = $5)
  AND ($6::text IS NULL OR estado = $6)
  AND ($7::text IS NULL OR estado <> $7)
  AND (NOT $8::boolean OR conflicto IS NOT NULL)
ORDER BY id DESC
LIMIT $9
`

type ListarPendientesParams struct {
	DespuesDe        int64
	Todas            bool
	EmpresaID        *int64
	Entidad          *string
	EntidadID        *string
	Estado           *string
	EstadoDistintoDe *string
	SoloConflicto    bool
	Limite           int32
}

// Más recientes primero. @todas = sin filtro de empresa (actor sistema); si no, empresa_id
// igual a la activa (null = modo sin conector).
func (q *Queries) ListarPendientes(ctx context.Context, arg ListarPendientesParams) ([]IntegracionPendiente, error) {
	rows, err := q.db.Query(ctx, listarPendientes,
		arg.DespuesDe,
		arg.Todas,
		arg.EmpresaID,
		arg.Entidad,
		arg.EntidadID,
		arg.Estado,
		arg.EstadoDistintoDe,
		arg.SoloConflicto,
		arg.Limite,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []IntegracionPendiente
	for rows.Next() {
		var i IntegracionPendiente
		if err := rows.Scan(
			&i.ID,
			&i.EmpresaID,
			&i.Sistema,
			&i.Operacion,
			&i.IdempotencyKey,
			&i.Entidad,
			&i.EntidadID,
			&i.Metodo,
			&i.Ruta,
			&i.Payload,
			&i.DependeDe,
			&i.DatosIncompletos,
			&i.Estado,
			&i.Intentos,
			&i.ProximoIntento,
			&i.TomadoEn,
			&i.UltimoError,
			&i.UltimoStatus,
			&i.HechoEn,
			&i.EventoID,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Conflicto,
			&i.ConflictoPayload,
			&i.ConflictoEn,
			&i.Respuesta,
			&i.Plantilla,
			&i.PorResolver,
			&i.Verificar,
			&i.TecnicoUsuarioID,
			&i.CodigoError,
			&i.ResueltoMotivo,
			&i.ResueltoPor,
			&i.ResueltoEn,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

